// Switchyard's own native settings (docs/spec/phone.md P13). Every native change goes through a
// config plugin; ios/ and android/ are generated by `expo prebuild` and never edited by hand.
//
// iOS:     NSSupportsLiveActivities = true (P12).
// Android: application android:allowBackup="false" (the keychain token never leaves the
//          phone, P3); RECORD_AUDIO and SYSTEM_ALERT_WINDOW removed if a library adds them;
//          android:usesCleartextTraffic only in development builds;
//          every androidx.work artifact is forced to one version (WORK_VERSION) in
//          app/build.gradle. react-native-android-widget declares work-runtime 2.8.1 while
//          expo-widgets' androidx.glance 1.2.0-rc01 pulls work-runtime-ktx 2.7.1; work 2.8
//          merged the ktx classes into work-runtime, so both on the classpath fail
//          :app:checkDebugDuplicateClasses (OneTimeWorkRequestKt, PeriodicWorkRequestKt).
//          Forcing the group to 2.8.1 turns ktx into an empty artifact.
// Android, no FCM (`withSyNoFirebase`, its own plugins entry, P13): no FCM entry point. The
//          com.google.firebase.* meta-data expo-notifications' plugin writes are dropped, and its
//          ExpoFirebaseMessagingService is removed from the merged manifest (tools:node="remove").
//          firebase-messaging stays on the classpath (expo-notifications' Kotlin links it) but is
//          never initialised: there is no google-services.json. It is listed BEFORE
//          expo-notifications in app.config.ts: manifest mods run in reverse order of the
//          plugins list, so it then sees (and drops) the meta-data expo-notifications adds.
//
// Wave 0 skeleton; owned by WP-W from wave 1 on (phases/8.md).
const { AndroidConfig, withAndroidManifest, withAppBuildGradle, withInfoPlist } = require('expo/config-plugins');

const REMOVED_PERMISSIONS = ['android.permission.RECORD_AUDIO', 'android.permission.SYSTEM_ALERT_WINDOW'];

const FCM_SERVICE = 'expo.modules.notifications.service.ExpoFirebaseMessagingService';

/** The manifest edit: no com.google.firebase meta-data, the FCM service removed. Idempotent. */
function stripFirebase(manifest) {
  manifest.manifest.$['xmlns:tools'] = manifest.manifest.$['xmlns:tools'] || 'http://schemas.android.com/tools';
  const app = (manifest.manifest.application || [])[0];
  if (!app) return manifest;
  app['meta-data'] = (app['meta-data'] || []).filter((m) => !String(m.$['android:name'] || '').startsWith('com.google.firebase'));
  const services = (app.service || []).filter((x) => x.$['android:name'] !== FCM_SERVICE);
  services.push({ $: { 'android:name': FCM_SERVICE, 'tools:node': 'remove' } });
  app.service = services;
  return manifest;
}

const WORK_VERSION = '2.8.1';
const WORK_MARKER = '// sy: align androidx.work';
const WORK_GRADLE = `
${WORK_MARKER}
configurations.all {
    resolutionStrategy.eachDependency { details ->
        if (details.requested.group == 'androidx.work') {
            details.useVersion '${WORK_VERSION}'
        }
    }
}
`;

// Idempotent: prebuild regenerates build.gradle, but a plugin may still run over one twice.
function alignWorkVersions(gradle) {
  return gradle.includes(WORK_MARKER) ? gradle : gradle + WORK_GRADLE;
}

function withSyWorkAlignment(config) {
  return withAppBuildGradle(config, (c) => {
    c.modResults.contents = alignWorkVersions(c.modResults.contents);
    return c;
  });
}

function withSyIos(config) {
  return withInfoPlist(config, (c) => {
    c.modResults.NSSupportsLiveActivities = true;
    return c;
  });
}

function withSyAndroid(config, { development }) {
  return withAndroidManifest(config, (c) => {
    const manifest = c.modResults;
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(manifest);
    app.$['android:allowBackup'] = 'false';
    if (development) {
      app.$['android:usesCleartextTraffic'] = 'true';
    } else {
      delete app.$['android:usesCleartextTraffic'];
    }
    // Library manifests are merged by Gradle, so a plain removal here would not stop them:
    // mark the permissions tools:node="remove" instead.
    manifest.manifest.$['xmlns:tools'] = manifest.manifest.$['xmlns:tools'] || 'http://schemas.android.com/tools';
    const perms = (manifest.manifest['uses-permission'] || []).filter(
      (p) => !REMOVED_PERMISSIONS.includes(p.$['android:name']),
    );
    for (const name of REMOVED_PERMISSIONS) {
      perms.push({ $: { 'android:name': name, 'tools:node': 'remove' } });
    }
    manifest.manifest['uses-permission'] = perms;
    return c;
  });
}

module.exports = function withSyNative(config, props = {}) {
  const development = props.development === true;
  config = withSyIos(config);
  config = withSyAndroid(config, { development });
  config = withSyWorkAlignment(config);
  return config;
};
module.exports.REMOVED_PERMISSIONS = REMOVED_PERMISSIONS;
module.exports.WORK_VERSION = WORK_VERSION;
module.exports.alignWorkVersions = alignWorkVersions;
module.exports.stripFirebase = stripFirebase;
/** The FCM-stripping manifest edit as a plugin of its own (see the header for its place). */
module.exports.withSyNoFirebase = function withSyNoFirebase(config) {
  return withAndroidManifest(config, (c) => {
    stripFirebase(c.modResults);
    return c;
  });
};
module.exports.FCM_SERVICE = FCM_SERVICE;
